```cpp
#include <iostream>
#include <map>
#include <string>
#include <vector>

class URLSearchParams {
public:
    URLSearchParams(const std::string& init = "") {
        if (!init.empty()) {
            parseInitString(init);
        }
    }

    void append(const std::string& name, const std::string& value) {
        params[name].push_back(value);
    }

    void deleteParam(const std::string& name) {
        params.erase(name);
    }

    std::string get(const std::string& name) const {
        auto it = params.find(name);
        if (it == params.end()) {
            return "";
        }
        if (!it->second.empty()) {
            return it->second.front();
        }
        return "";
    }

    std::vector<std::string> getAll(const std::string& name) const {
        auto it = params.find(name);
        if (it == params.end()) {
            return {};
        }
        return it->second;
    }

    bool has(const std::string& name) const {
        return params.find(name) != params.end();
    }

    void set(const std::string& name, const std::string& value) {
        params[name] = {value};
    }

    void sort() {
        for (auto& pair : params) {
            std::sort(pair.second.begin(), pair.second.end());
        }
    }

    __declspec(property(get = toString, put = fromString)) std::string stringifier;
    std::string toString() const {
        return buildQueryString();
    }

    void fromString(const std::string& value) {
        params.clear();
        parseInitString(value);
    }

private:
    std::map<std::string, std::vector<std::string>> params;

    std::string buildQueryString() const {
        std::string result = "";

        for (const auto& pair : params) {
            for (size_t i = 0; i < pair.second.size(); ++i) {
                if (!result.empty()) {
                    result += "&";
                }

                result += pair.first + "=" + pair.second[i];
            }
        }
        return result;
    }

