```

2. Create an `index.html` file in your project root folder with the following content:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Video Chat</title>
</head>
<body>
  <video id="localVideo" autoplay muted></video>
  <video id="remoteVideo" autoplay></video>

  <script src="/socket.io/socket.io.js"></script>
  <script>
    const socket = io();

    // Get HTML elements
    const localVideo = document.getElementById('localVideo');
    const remoteVideo = document.getElementById('remoteVideo');

    // Set up a connection between two users (peerConnection)
    const pcConfig = {'iceServers': [{'urls': 'stun:stun.l.google.com:19302'}]};
    const pc = new RTCPeerConnection(pcConfig);

    // Handling Local Media Stream
    navigator.mediaDevices.getUserMedia({ video: true, audio: true })
      .then(stream => {
        localVideo.srcObject = stream;

        // Add the local stream to the peerConnection
        stream.getTracks().forEach(track => pc.addTrack(track, stream));
      });

    // Handling Remote Media Stream
    pc.ontrack = (event) => {
      remoteVideo.srcObject = event.streams[0];
    };

    // Signaling
    pc.onicecandidate = (event) => {
      if (event.candidate) {
        socket.emit('signal', {'type': 'ice', 'data': event.candidate});
      }
    };

    // Listening for incoming signals
    socket.on('signal', (data) => {
      if (data.type === 'offer') {
        pc.setRemoteDescription(new RTCSessionDescription(data.data))
          .then(() => pc.createAnswer())
          .then(answer => pc.setLocalDescription(answer))
          .then(() => {
            socket.emit('signal', {'type': 'answer', 'data': pc.localDescription});
          });
      } else if (data.type === 'answer') {
        pc.setRemoteDescription(new RTCSessionDescription(data.data));
      } else if (data.type === 'ice') {
        pc.addIceCandidate(new RTCIceCandidate(data.data));
      }
    });

    // Start a call after the page is loaded
    setTimeout(() => {
      pc.createOffer()
        .then(offer => pc.setLocalDescription(offer))
        .then(() => {
          socket.emit('signal', {'type': 'offer', 'data': pc.localDescription});
        });
    }, 1000);
  </script>
</body>
</html>
```

